// Takes a scene's lottie.json (as generated by build-lottie-calibration.mjs,
// with a relative-path image asset) plus its bg.png, and writes an app-ready
// copy with the image embedded as base64 (e:1) — avoids needing any
// assetsPath/static-file wiring for lottie-react/lottie-web in the Vite app.
//
// Usage:
//   node tools/build/embed-lottie-image.mjs <scene.json> <bg.png> <out.json>
import fs from 'node:fs'

const [sceneJsonPath, pngPath, outPath] = process.argv.slice(2)
if (!sceneJsonPath || !pngPath || !outPath) {
  console.error('usage: node embed-lottie-image.mjs <scene.json> <bg.png> <out.json>')
  process.exit(1)
}

const doc = JSON.parse(fs.readFileSync(sceneJsonPath, 'utf8'))
const b64 = fs.readFileSync(pngPath).toString('base64')

doc.assets = doc.assets.map((a) =>
  a.e === 0 ? { ...a, p: `data:image/png;base64,${b64}`, e: 1 } : a,
)

fs.writeFileSync(outPath, JSON.stringify(doc))
console.log('wrote', outPath, '(', fs.statSync(outPath).size, 'bytes )')
